int main() {
    Solution sol;
    vector<vector<int>> arg0;
    string s0; getline(cin >> ws, s0);
    // Simplified parser for [[1,3],[2,6]]
    vector<int> curr0;
    string temp0 = "";
    bool in_array = false;
    for(int i = 1; i < s0.size()-1; i++) {
        char c = s0[i];
        if (c == '[') { in_array = true; }
        else if (c == ']') {
            if(temp0!="") { curr0.push_back(stoi(temp0)); temp0=""; }
            arg0.push_back(curr0);
            curr0.clear();
            in_array = false;
        }
        else if (c == ',') {
            if(in_array && temp0!="") { curr0.push_back(stoi(temp0)); temp0=""; }
        } else { temp0 += c; }
    }
    auto res = sol.method(arg0);
    cout << "[";
    for(int i=0; i<res.size(); i++) {
        cout << "[";
        for(int j=0; j<res[i].size(); j++) {
            cout << res[i][j] << (j==res[i].size()-1 ? "" : ",");
        }
        cout << "]" << (i==res.size()-1 ? "" : ",");
    }
    cout << "]" << endl;
    return 0;
}

